mapper.select:
   select * from (
   	 	select 
	        REPORTUUID reportuuid,
		    TERMID termid,
		    REPORTTYPE reporttype,
		    STARTDATE startdate,
		    ENDDATE enddate,
		    ISSUE_PARTY_ID issuePartyId,
		    ISSUE_PARTY_NAME issuePartyName,
		    REPORTFREQU reportfrequ,
		    SUBMIT_TIME submitTime,
		    CHB_SUBMIT_DEADLINE chbSubmitDeadline,
