				and DATE_FORMAT(STATUS_DATE,'%Y-%m-%d') >= #{statusDateStart,jdbcType=VARCHAR}


				and DATE_FORMAT(STATUS_DATE,'%Y-%m-%d') <= #{statusDateEnd,jdbcType=VARCHAR}


				and DATE_FORMAT(SUBMIT_TIME,'%Y-%m-%d') >= #{submitDateStart,jdbcType=VARCHAR}


